1	import { Construction, Plane } from 'lucide-react';
2	import { useNavigate, useParams } from 'react-router';
3	import { MaintenanceFleetDocumentsTab } from '../components/maintenance-fleet-documents-tab';
4	import { MaintenanceHubAircraftInspections } from './maintenance-hub-aircraft-inspections';
5	import { MaintenanceHubAircraftLogbook } from './maintenance-hub-aircraft-logbook';
6	import { MaintenanceHubAircraftWorkOrders } from './maintenance-hub-aircraft-work-orders';
7	
8	interface MaintenanceHubAircraftStubProps {
9	  /** The name of the feature section (e.g. "Squawks", "Documents") */
10	  sectionName: string;
11	}
12	
13	/**
14	 * Placeholder page for Maintenance Hub per-aircraft sub-sections that are
15	 * planned but not yet fully implemented. Provides a consistent "coming soon"
16	 * UI while the navigation structure is wired up.
17	 *
18	 * Sections with a real implementation delegate immediately:
19	 *   - "Documents"    → MaintenanceFleetDocumentsTab
20	 *   - "Work Orders"  → MaintenanceHubAircraftWorkOrders
21	 *   - "Logbooks"     → MaintenanceHubAircraftLogbook
22	 *
23	 * Note: "Discrepancy Log" is now wired directly in routes.tsx and no longer
24	 * delegates through this stub.
25	 */
26	export function MaintenanceHubAircraftStub({
27	  sectionName,
28	}: MaintenanceHubAircraftStubProps) {
29	  const { equipmentId } = useParams<{ equipmentId: string }>();
30	  const navigate = useNavigate();
31	
32	  // Sections with real implementations — delegate immediately
33	  if (sectionName === 'Documents') {
34	    return <MaintenanceFleetDocumentsTab />;
35	  }
36	  if (sectionName === 'Work Orders') {
37	    return <MaintenanceHubAircraftWorkOrders />;
38	  }
39	  if (sectionName === 'Logbooks') {
40	    return <MaintenanceHubAircraftLogbook />;
41	  }
42	  if (sectionName === 'Inspections') {
43	    return <MaintenanceHubAircraftInspections />;
44	  }
45	
46	  return (
47	    <div className="p-6 max-w-2xl mx-auto">
48	      <div className="rounded-xl border border-gray-200 bg-white p-10 text-center">
49	        <div className="flex items-center justify-center w-14 h-14 rounded-xl bg-teal-50 border border-teal-200 mx-auto mb-4">
50	          <Construction className="w-7 h-7 text-teal-600" />
51	        </div>
52	        <h2 className="text-xl font-bold text-gray-900 mb-2">{sectionName}</h2>
53	        <p className="text-gray-500 text-sm mb-6 leading-relaxed">
54	          This aircraft section is coming soon. The navigation is wired up and
55	          ready — full functionality will be available in an upcoming release.
56	        </p>
57	        <div className="flex items-center justify-center gap-3">
58	          <button
59	            onClick={() =>
60	              navigate(`/maintenance-hub/fleet/${equipmentId ?? ''}/dashboard`)
61	            }
62	            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-50 border border-teal-200 text-teal-700 hover:bg-teal-100 text-sm font-medium transition-colors"
63	          >
64	            <Plane className="w-4 h-4" />
65	            Aircraft Dashboard
66	          </button>
67	          <button
68	            onClick={() => navigate('/maintenance-hub/fleet')}
69	            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-white border border-gray-200 text-gray-600 hover:bg-gray-50 text-sm font-medium transition-colors"
70	          >
71	            Fleet Overview
72	          </button>
73	        </div>
74	      </div>
75	    </div>
76	  );
77	}
