57	  | 'open'
58	  | 'in_progress'
59	  | 'deferred'
60	  | 'pending_signoff'
61	  | 'closed';
62	type FoundDuring =
63	  | 'annual_inspection'
64	  | 'hundred_hr'
65	  | 'preflight'
66	  | 'in_flight'
67	  | 'postflight'
68	  | 'line_maintenance'
69	  | 'ramp_check'
70	  | 'other';
