80	  ataChapter: string | null;
81	  foundAt: string;
82	  aircraftHours: string | null;
83	  airworthiness: string;
84	  linkedWorkOrderId: string | null;
85	  closedAt: string | null;
86	  updatedAt: string;
87	  createdAt: string;
88	  foundByUserId: string | null;
