251	// ─── Helpers ─────────────────────────────────────────────────────────────────
252	
253	function formatDate(dateStr: string | null | undefined): string {
254	  if (!dateStr) return '—';
255	  return new Date(dateStr).toLocaleDateString('en-US', {
256	    month: 'short',
257	    day: 'numeric',
258	    year: 'numeric',
259	  });
260	}
261	
262	function daysUntil(dateStr: string | null): number | null {
263	  if (!dateStr) return null;
264	  const due = new Date(dateStr);
265	  const now = new Date();
266	  now.setHours(0, 0, 0, 0);
267	  due.setHours(0, 0, 0, 0);
268	  return Math.floor((due.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
269	}
270	
271	function thisYear(): number {
272	  return new Date().getFullYear();
273	}
274	
275	// ─── Sub-components ───────────────────────────────────────────────────────────
276	
