379	      <span className="text-xs font-semibold uppercase tracking-wider flex-1">
380	        {label}
381	      </span>
382	      <span className="text-xs font-bold">{cnt}</span>
383	    </button>
384	  );
385	}
386	
387	function DiscRow({
388	  disc,
389	  selected,
390	  onClick,
391	  onMenuAction,
392	}: {
393	  disc: DiscrepancyItem;
394	  selected: boolean;
395	  onClick: () => void;
396	  onMenuAction: (action: string) => void;
397	}) {
398	  const deferral = disc.latestDeferral;
399	  const daysLeft =
400	    disc.status === 'deferred' && deferral
401	      ? daysUntil(deferral.returnByDate)
402	      : null;
403	
404	  return (
405	    <div
406	      role="button"
407	      tabIndex={0}
408	      onClick={onClick}
409	      onKeyDown={(e) => e.key === 'Enter' && onClick()}
410	      className={cn(
411	        'relative flex items-start gap-3 rounded-xl border px-4 py-3 cursor-pointer transition-colors group',
412	        selected
413	          ? 'border-teal-400 bg-teal-50/60'
414	          : 'border-gray-200 bg-white hover:bg-gray-50',
415	      )}
416	    >
417	      {/* Severity dot */}
418	      <span className="mt-1.5">
419	        <SeverityDot severity={disc.severity} />
420	      </span>
421	
422	      {/* Main content */}
423	      <div className="flex-1 min-w-0">
424	        <div className="flex items-start justify-between gap-2 mb-0.5">
425	          <p className="text-sm font-semibold text-gray-900 leading-snug truncate">
426	            {disc.title}
427	          </p>
428	          <div className="flex items-center gap-1 flex-shrink-0">
429	            <SeverityBadge severity={disc.severity} />
430	            <StatusBadge status={disc.status} />
431	          </div>
432	        </div>
433	        <div className="flex items-center gap-1.5 flex-wrap">
434	          <span className="text-[11px] text-gray-400 font-mono">
435	            {disc.discNumber}
436	          </span>
437	          <span className="text-gray-300 text-[11px]">·</span>
438	          <span className="text-[11px] text-gray-500">
439	            {FOUND_DURING_LABELS[disc.foundDuring]}
440	          </span>
441	          <span className="text-gray-300 text-[11px]">·</span>
442	          <span className="text-[11px] text-gray-500">
443	            {formatDate(disc.foundAt)}
444	          </span>
445	          {disc.linkedWorkOrderId && (
446	            <>
447	              <span className="text-gray-300 text-[11px]">·</span>
448	              <span className="text-[11px] text-teal-600 font-medium">
449	                WO linked
450	              </span>
451	            </>
452	          )}
453	        </div>
454	        {/* Deferral date warning */}
455	        {disc.status === 'deferred' && deferral && (
456	          <div className="mt-1">
457	            <span
458	              className={cn(
459	                'text-[11px] font-medium',
460	                daysLeft !== null && daysLeft < 0
461	                  ? 'text-red-600'
462	                  : daysLeft !== null && daysLeft <= 14
463	                    ? 'text-amber-600'
464	                    : 'text-gray-500',
465	              )}
466	            >
467	              Return by {formatDate(deferral.returnByDate)}
468	              {daysLeft !== null && daysLeft < 0
469	                ? ` · ${Math.abs(daysLeft)}d overdue`
470	                : daysLeft !== null && daysLeft === 0
471	                  ? ' · Due today'
472	                  : daysLeft !== null && daysLeft <= 14
473	                    ? ` · ${daysLeft}d remaining`
474	                    : null}
475	            </span>
476	          </div>
477	        )}
478	      </div>
479	
480	      {/* Three-dot menu */}
481	      <div
482	        className="mt-0.5"
483	        onClick={(e) => e.stopPropagation()}
484	        onKeyDown={(e) => e.stopPropagation()}
485	      >
486	        <DropdownMenu>
487	          <DropdownMenuTrigger asChild>
488	            <button
489	              type="button"
490	              className="p-1 rounded hover:bg-gray-100 text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity"
491	              aria-label="Row actions"
492	            >
493	              <MoreHorizontal className="w-4 h-4" />
494	            </button>
495	          </DropdownMenuTrigger>
496	          <DropdownMenuContent align="end" className="w-44">
497	            <DropdownMenuItem
498	              onClick={(e) => {
499	                e.stopPropagation();
500	                onMenuAction('edit');
501	              }}
502	            >
503	              Edit
504	            </DropdownMenuItem>
505	            {disc.status !== 'deferred' && disc.status !== 'closed' && (
506	              <DropdownMenuItem
507	                onClick={(e) => {
508	                  e.stopPropagation();
509	                  onMenuAction('defer');
510	                }}
511	              >
512	                Defer
513	              </DropdownMenuItem>
514	            )}
515	            {disc.status !== 'closed' && (
516	              <DropdownMenuItem
517	                onClick={(e) => {
518	                  e.stopPropagation();
519	                  onMenuAction('signoff');
520	                }}
521	              >
522	                Sign off
523	              </DropdownMenuItem>
524	            )}
525	            {disc.severity !== 'aog' && disc.status !== 'closed' && (
526	              <DropdownMenuItem
527	                onClick={(e) => {
528	                  e.stopPropagation();
529	                  onMenuAction('escalate');
530	                }}
531	              >
532	                Escalate to AOG
533	              </DropdownMenuItem>
534	            )}
535	            <DropdownMenuSeparator />
536	            <DropdownMenuItem
537	              variant="destructive"
538	              onClick={(e) => {
539	                e.stopPropagation();
540	                onMenuAction('delete');
541	              }}
542	            >
543	              Delete
544	            </DropdownMenuItem>
545	          </DropdownMenuContent>
546	        </DropdownMenu>
547	      </div>
548	    </div>
549	  );
550	}
551	
552	// ─── Detail Panel ─────────────────────────────────────────────────────────────
553	
554	function DetailPanel({
555	  disc,
556	  onClose,
557	  onDefer,
558	  onSignoff,
559	  onPendingSignoff,
560	  onEscalate,
561	  onCreateOrLinkWo,
562	  orgId,
563	  equipmentId,
564	  aircraftInfo,
565	}: {
566	  disc: DetailDiscrepancy | null;
567	  onClose: () => void;
568	  onDefer: () => void;
569	  onSignoff: () => void;
570	  onPendingSignoff: () => void;
571	  onEscalate: () => void;
572	  onCreateOrLinkWo: () => void;
573	  orgId: string;
574	  equipmentId: string;
575	  aircraftInfo: {
576	    tailNumber: string;
577	    make: string;
578	    model: string;
579	    year: number | null;
580	    hobbsTime: number | null;
581	    totalHours: number | null;
582	  } | null;
583	}) {
584	  const [adBannerDismissed, setAdBannerDismissed] = useState(false);
585	  const [adCheck, setAdCheck] = useState<{
586	    relatedAds: Array<{ adNumber: string; title: string; relevance: string }>;
587	    hasRelevantAds: boolean;
588	    summary: string;
589	  } | null>(null);
590	
591	  // Run AD check when disc is loaded
592	  useEffect(() => {
593	    if (!disc || disc.status === 'closed') return;
594	    setAdCheck(null);
595	    setAdBannerDismissed(false);
596	
597	    const timeout = setTimeout(async () => {
598	      try {
599	        const res = await fetch(`${API}/discrepancy-ai/ad-check`, {
600	          method: 'POST',
601	          headers: { 'Content-Type': 'application/json' },
602	          body: JSON.stringify({
603	            orgId,
604	            title: disc.title,
