1090	function isValidAtaChapter(value: string): boolean {
1091	  const trimmed = value.trim().toLowerCase();
1092	  return ATA_CHAPTERS.some(
1093	    (c) =>
1094	      c.code.toLowerCase() === trimmed ||
1095	      `${c.code.toLowerCase()} — ${c.name.toLowerCase()}` === trimmed ||
1096	      trimmed.startsWith(`${c.code.toLowerCase()} `) ||
1097	      trimmed.startsWith(`${c.code.toLowerCase()}—`),
1098	  );
1099	}
