import { db } from '@/lib/db';
import { hasOverdueGroundingInspection } from '@/lib/maintenance/grounding-inspections';
import {
  DISC_TERMINAL_STATUSES,
  SQUAWK_TERMINAL_STATUSES,
} from '@/lib/maintenance/status-constants';
import * as schema from '@/lib/schema';
import { and, count, eq, inArray, not } from 'drizzle-orm';

/**
 * Canonical sets for "what counts as an active squawk".
 *
 * Used to deduplicate filter logic across:
 *   - maybeUngroundEquipment (counts active grounding squawks/discs)
 *   - equipment-profile.tsx badge counter (KV-side)
 *   - PUT /maintenance grounding decision (KV-side)
 *   - any future reader that needs to ask "is this active right now"
 *
 * Drift between these filter sets is what produced the N1207H "phantom
 * duplicate" report on 2026-05-02 — the badge counted a voided em-record
 * because its filter only excluded ['completed','cancelled'].
 */

/**
 * Returns true if the equipment has any active grounding source — an open
 * grounding squawk, an open grounded_aog discrepancy, or an overdue inspection
 * that requires grounding. This is the canonical answer to "is this aircraft
 * currently grounded by data".
 */
async function hasActiveGroundingSource(
  equipmentId: string,
  orgId: string,
): Promise<boolean> {
  const [openSquawkRow] = await db
    .select({ n: count() })
    .from(schema.squawks)
    .where(
      and(
        eq(schema.squawks.equipmentId, equipmentId),
        eq(schema.squawks.flightSchoolId, orgId),
