146	// ─── Helpers ─────────────────────────────────────────────────────────────────
147	
148	// Parses date strings without a UTC shift in negative-UTC timezones.
149	// "YYYY-MM-DD" and "YYYY-MM-DDTHH:mm:ss.sssZ" both return local midnight
150	// so `new Date("2026-05-10")` → May 9 in CT is fixed to May 10.
151	function parseLocalDate(s: string): Date {
152	  const dateOnly = /^\d{4}-\d{2}-\d{2}$/.exec(s);
153	  if (dateOnly) {
154	    const [y, m, d] = s.split('-').map(Number);
155	    return new Date(y, m - 1, d);
156	  }
157	  const tsWithDate = /^(\d{4}-\d{2}-\d{2})T/.exec(s);
158	  if (tsWithDate) {
159	    const [y, m, d] = tsWithDate[1].split('-').map(Number);
160	    return new Date(y, m - 1, d);
161	  }
162	  return new Date(s);
163	}
164	
165	function formatDate(dateStr: string | null | undefined): string {
166	  if (!dateStr) return '—';
167	  return parseLocalDate(dateStr).toLocaleDateString('en-US', {
168	    month: 'short',
169	    day: 'numeric',
170	    year: 'numeric',
171	  });
172	}
173	
174	function formatRelative(dateStr: string | null | undefined): string {
175	  if (!dateStr) return '';
176	  const d = new Date(dateStr);
177	  const now = new Date();
178	  const diffMs = now.getTime() - d.getTime();
179	  const diffMins = Math.floor(diffMs / 60000);
180	  if (diffMins < 1) return 'just now';
181	  if (diffMins < 60) return `${diffMins}m ago`;
182	  const diffHrs = Math.floor(diffMins / 60);
183	  if (diffHrs < 24) return `${diffHrs}h ago`;
184	  const diffDays = Math.floor(diffHrs / 24);
185	  if (diffDays < 7) return `${diffDays}d ago`;
186	  return formatDate(dateStr);
187	}
188	
189	function daysOverdue(dueDateStr: string | null): number | null {
190	  if (!dueDateStr) return null;
191	  const due = new Date(dueDateStr);
192	  const now = new Date();
193	  now.setHours(0, 0, 0, 0);
194	  const diff = Math.floor(
195	    (now.getTime() - due.getTime()) / (1000 * 60 * 60 * 24),
196	  );
197	  return diff > 0 ? diff : null;
198	}
199	
200	function avgDaysToComplete(wos: PerTailWorkOrder[]): number | null {
201	  const completed = wos.filter(
202	    (w) => (w.status === 'complete' || w.status === 'closed') && w.completedAt,
203	  );
204	  if (completed.length === 0) return null;
205	  const avgMs =
206	    completed.reduce((sum, w) => {
207	      const start = new Date(w.createdAt).getTime();
208	      const end = new Date(w.completedAt!).getTime();
209	      return sum + (end - start);
210	    }, 0) / completed.length;
211	  return Math.round((avgMs / (1000 * 60 * 60 * 24)) * 10) / 10;
212	}
213	
214	function sortWos(
215	  wos: PerTailWorkOrder[],
216	  sortKey: SortKey,
217	): PerTailWorkOrder[] {
218	  return [...wos].sort((a, b) => {
219	    if (sortKey === 'dueDate') {
220	      if (!a.dueDate && !b.dueDate) return 0;
221	      if (!a.dueDate) return 1;
222	      if (!b.dueDate) return -1;
223	      return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
224	    }
225	    if (sortKey === 'priority') {
226	      return (
227	        (PRIORITY_ORDER[a.priority] ?? 99) - (PRIORITY_ORDER[b.priority] ?? 99)
228	      );
229	    }
230	    if (sortKey === 'status') {
231	      return (STATUS_ORDER[a.status] ?? 99) - (STATUS_ORDER[b.status] ?? 99);
232	    }
233	    if (sortKey === 'updatedAt') {
234	      return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
235	    }
236	    return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
237	  });
238	}
