1038	
1039	  const loadWorkOrders = useCallback(async () => {
1040	    if (!orgId || !equipmentId) return;
1041	
1042	    // Cancel any in-flight request before starting a new one
1043	    abortControllerRef.current?.abort();
1044	    const controller = new AbortController();
1045	    abortControllerRef.current = controller;
1046	
1047	    setLoading(true);
1048	    setError(null);
1049	
1050	    const doFetch = async () => {
1051	      const params = new URLSearchParams({ orgId, equipmentId });
1052	      if (activeLocation?.id) params.set('locationId', activeLocation.id);
1053	      const res = await fetch(`${API}/work-orders?${params}`, {
1054	        signal: controller.signal,
1055	      });
1056	      if (!res.ok) {
1057	        const msg = await res.text();
1058	        throw new Error(msg || `Request failed: ${res.status}`);
1059	      }
1060	      return res.json() as Promise<{ workOrders: PerTailWorkOrder[] }>;
1061	    };
1062	
1063	    try {
