1069	        await new Promise((r) => setTimeout(r, 1000));
1070	        data = await doFetch();
1071	      }
1072	      if (controller.signal.aborted) return;
1073	      const wos = data!.workOrders ?? [];
1074	      setWorkOrders(wos);
1075	      if (wos.length > 0) {
1076	        if (wos[0].tailNumber) setTailNumber(wos[0].tailNumber);
