1081	      if (err instanceof DOMException && err.name === 'AbortError') return;
1082	      const msg =
1083	        err instanceof Error
1084	          ? err.message
1085	          : typeof err === 'object' && err !== null
1086	            ? JSON.stringify(err)
1087	            : String(err);
1088	      console.error('[MaintenanceHubAircraftWorkOrders] Failed to load:', msg);
1089	      toast.error('Failed to load work orders. Please try again.');
