1126	          };
1127	        }>;
1128	      })
1129	      .then((data) => {
1130	        if (data?.equipment) {
1131	          setEngineStats({
1132	            tailNumber: data.equipment.tailNumber,
1133	            make: data.equipment.make,
1134	            model: data.equipment.model,
1135	            hobbsTime: data.equipment.hobbsTime,
1136	            tachTime: data.equipment.tachTime,
1137	            timeSinceOverhaul: data.equipment.timeSinceOverhaul,
1138	            tboHours: data.equipment.tboHours,
1139	          });
1140	        }
1141	      })
1142	      .catch(() => {
1143	        // Right rail stats are non-critical — fail silently
1144	      })
1145	      .finally(() => setEngineStatsLoading(false));
1146	  }, [orgId, equipmentId]);
1147	
1148	  // ─── Derived Metrics ─────────────────────────────────────────────────────────
1149	
1150	  const activeWos = workOrders.filter(
1151	    (wo) => !['complete', 'closed', 'voided'].includes(wo.status),
1152	  );
