1161	  const overdueCount = overdueWos.length;
1162	  const oldestOverdueDays =
1163	    overdueCount > 0
1164	      ? Math.max(...overdueWos.map((wo) => daysOverdue(wo.dueDate) ?? 0))
1165	      : null;
1166	
1167	  const openCount = workOrders.filter(
1168	    (wo) => !['complete', 'closed', 'voided'].includes(wo.status),
1169	  ).length;
