269	export function MaintenanceHubAircraftDiscrepancyLog() {
270	  const { equipmentId } = useParams<{ equipmentId: string }>();
271	
272	  const [aircraft, setAircraft] = useState<AircraftInfo | null>(null);
273	  const [discrepancies, setDiscrepancies] = useState<DiscrepancyEvent[]>([]);
274	  const [loading, setLoading] = useState(true);
275	  const [error, setError] = useState<string | null>(null);
276	  const [activeTab, setActiveTab] = useState<TabFilter>('all');
277	  const [searchQuery, setSearchQuery] = useState('');
278	
279	  const loadData = useCallback(async () => {
280	    if (!equipmentId) return;
281	    setLoading(true);
282	    setError(null);
283	
284	    const doFetch = async () => {
285	      // Forwards X-Managed-School-Id so a super-admin resolves to the school
286	      // they manage; without it the endpoint's tenant guard 403s.
287	      const res = await fetch(`${API}/discrepancy-log/${equipmentId}`, {
288	        headers: getServerApiHeaders(),
289	      });
290	      if (!res.ok) {
291	        const msg = await res.text();
292	        throw new Error(msg || `Request failed: ${res.status}`);
293	      }
294	      return res.json() as Promise<{
295	        aircraft: AircraftInfo;
296	        discrepancies: DiscrepancyEvent[];
297	      }>;
298	    };
299	
300	    try {
301	      let data: { aircraft: AircraftInfo; discrepancies: DiscrepancyEvent[] };
302	      try {
303	        data = await doFetch();
304	      } catch {
305	        // One retry after 1 s — handles Neon cold-start
306	        await new Promise((r) => setTimeout(r, 1000));
307	        data = await doFetch();
308	      }
309	      setAircraft(data.aircraft);
310	      setDiscrepancies(data.discrepancies ?? []);
311	    } catch (err) {
312	      const msg =
313	        err instanceof Error
314	          ? err.message
315	          : typeof err === 'object' && err !== null
316	            ? JSON.stringify(err)
317	            : String(err);
318	      console.error(
319	        '[MaintenanceHubAircraftDiscrepancyLog] Failed to load:',
320	        msg,
321	      );
322	      toast.error('Failed to load discrepancy log. Please try again.');
323	      setError('Failed to load discrepancy log. Please try again.');
324	    } finally {
325	      setLoading(false);
326	    }
327	  }, [equipmentId]);
328	
329	  useEffect(() => {
330	    void loadData();
331	  }, [loadData]);
332	
333	  // ─── Derived State ──────────────────────────────────────────────────────────
334	
335	  const hobbsCount = discrepancies.filter((e) => e.hobbsDiscrepancy).length;
336	  const tachCount = discrepancies.filter((e) => e.tachDiscrepancy).length;
337	  const bothCount = discrepancies.filter(
338	    (e) => e.hobbsDiscrepancy && e.tachDiscrepancy,
339	  ).length;
340	  const total = discrepancies.length;
341	
342	  const tabCounts: Record<TabFilter, number> = {
343	    all: total,
344	    hobbs: discrepancies.filter((e) => e.hobbsDiscrepancy && !e.tachDiscrepancy)
345	      .length,
346	    tach: discrepancies.filter((e) => e.tachDiscrepancy && !e.hobbsDiscrepancy)
347	      .length,
348	    both: bothCount,
349	  };
350	
351	  const filtered = discrepancies
352	    .filter((e) => {
353	      if (activeTab === 'hobbs')
354	        return e.hobbsDiscrepancy && !e.tachDiscrepancy;
355	      if (activeTab === 'tach') return e.tachDiscrepancy && !e.hobbsDiscrepancy;
356	      if (activeTab === 'both') return e.hobbsDiscrepancy && e.tachDiscrepancy;
357	      return true;
358	    })
359	    .filter((e) => {
360	      if (!searchQuery.trim()) return true;
361	      const q = searchQuery.toLowerCase();
362	      return (
363	        (e.studentName?.toLowerCase().includes(q) ?? false) ||
364	        (e.instructorName?.toLowerCase().includes(q) ?? false) ||
365	        e.title.toLowerCase().includes(q) ||
366	        formatDate(e.startAt).toLowerCase().includes(q)
367	      );
368	    });
369	
370	  const displayTail = aircraft?.tailNumber ?? equipmentId ?? 'This Aircraft';
371	
372	  const aircraftLabel = aircraft
373	    ? [
374	        aircraft.make,
375	        aircraft.model,
376	        aircraft.year ? String(aircraft.year) : null,
377	      ]
378	        .filter(Boolean)
379	        .join(' · ')
380	    : '';
381	
382	  // ─── Render ─────────────────────────────────────────────────────────────────
383	
384	  return (
385	    <div className="p-6 flex flex-col gap-5 max-w-[1600px] mx-auto">
386	      {/* Page header */}
387	      {aircraft && (
388	        <div className="mb-1">
389	          <h2 className="text-lg font-semibold text-gray-900">{displayTail}</h2>
390	          {aircraftLabel && (
391	            <p className="text-sm text-gray-500">{aircraftLabel}</p>
392	          )}
393	        </div>
394	      )}
395	
396	      {/* Stat Bar */}
397	      <div className="grid grid-cols-3 gap-3">
398	        <StatCard
399	          label="Total"
400	          value={total}
401	          valueColor={total > 0 ? 'text-rose-600' : 'text-gray-900'}
402	        />
403	        <StatCard
404	          label="Hobbs"
405	          value={hobbsCount}
406	          valueColor={hobbsCount > 0 ? 'text-amber-600' : 'text-gray-900'}
407	        />
408	        <StatCard
409	          label="Tach"
410	          value={tachCount}
411	          valueColor={tachCount > 0 ? 'text-blue-600' : 'text-gray-900'}
412	        />
413	      </div>
414	
415	      {/* Search bar */}
416	      <div className="relative">
417	        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
418	        <input
419	          type="text"
420	          placeholder="Search by pilot, instructor, or date…"
421	          value={searchQuery}
422	          onChange={(e) => setSearchQuery(e.target.value)}
423	          className="w-full pl-9 pr-3 py-2 text-sm bg-white border border-gray-200 rounded-xl text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-1 focus:ring-teal-500/50 focus:border-teal-500"
424	        />
425	      </div>
426	
427	      {/* Filter Tabs */}
428	      <div className="border-b border-gray-200">
429	        <div className="flex items-end gap-0 flex-wrap -mb-px">
430	          {TAB_DEFS.map(({ key, label }) => (
431	            <button
432	              key={key}
433	              type="button"
434	              onClick={() => setActiveTab(key)}
435	              className={cn(
436	                'inline-flex items-center gap-1.5 px-3 py-2 text-[12px] font-medium transition-colors border-b-2',
437	                activeTab === key
438	                  ? 'border-teal-600 text-teal-600'
439	                  : 'border-transparent text-gray-500 hover:text-gray-900 hover:border-gray-300',
440	              )}
441	            >
442	              {label}
443	              {tabCounts[key] > 0 && (
444	                <span
445	                  className={cn(
446	                    'inline-flex items-center justify-center min-w-[1.125rem] h-[1.125rem] rounded-full text-[10px] font-bold px-1',
447	                    activeTab === key
448	                      ? 'bg-teal-100 text-teal-700'
449	                      : 'bg-gray-100 text-gray-600',
450	                  )}
451	                >
452	                  {tabCounts[key]}
453	                </span>
454	              )}
455	            </button>
456	          ))}
457	        </div>
458	      </div>
459	
460	      {/* Content */}
461	      {loading ? (
462	        <div className="flex items-center justify-center h-48">
463	          <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
464	        </div>
465	      ) : error ? (
466	        <div className="rounded-2xl border border-red-200 bg-red-50 p-8 flex flex-col items-center gap-3">
467	          <AlertCircle className="w-8 h-8 text-red-400" />
468	          <p className="text-sm font-medium text-red-700">
469	            Unable to load discrepancy log
470	          </p>
471	          <p className="text-[12px] text-gray-500 text-center max-w-[280px]">
472	            {error}
473	          </p>
474	          <button
475	            type="button"
476	            onClick={() => void loadData()}
477	            className="mt-1 px-3 py-1.5 text-[12px] font-medium text-teal-600 border border-teal-300 rounded-lg hover:bg-teal-50 transition-colors"
478	          >
479	            Try Again
480	          </button>
481	        </div>
482	      ) : total === 0 ? (
483	        /* No discrepancies at all for this aircraft */
484	        <div className="rounded-2xl border border-gray-200 bg-gray-50 p-10 flex flex-col items-center gap-3 text-center">
485	          <div className="flex items-center justify-center w-14 h-14 rounded-2xl bg-white border border-gray-200 mx-auto">
486	            <CheckCircle2 className="w-7 h-7 text-emerald-500" />
487	          </div>
488	          <p className="text-base font-semibold text-gray-900">
