490	          </p>
491	          <p className="text-sm text-gray-500 max-w-[320px]">
492	            Hobbs and Tach meter readings have matched on file values for all
493	            recorded flights. Discrepancies are flagged automatically during the
494	            check-in flow.
495	          </p>
496	        </div>
497	      ) : filtered.length === 0 ? (
498	        /* Discrepancies exist but none match current filter/search */
499	        <div className="rounded-2xl border border-gray-200 bg-gray-50 p-8 flex flex-col items-center gap-3 text-center">
500	          <CircleSlash className="w-10 h-10 text-gray-400" />
501	          <p className="text-sm font-medium text-gray-600">
502	            {searchQuery
503	              ? `No discrepancies matching "${searchQuery}"`
504	              : `No ${activeTab === 'hobbs' ? 'Hobbs-only' : activeTab === 'tach' ? 'Tach-only' : 'mixed'} discrepancies`}
505	          </p>
506	        </div>
507	      ) : (
508	        /* Discrepancy list */
509	        <div className="flex flex-col gap-3">
510	          {filtered.map((event) => (
511	            <DiscrepancyRow key={event.id} event={event} />
512	          ))}
513	        </div>
514	      )}
515	
516	      {/* Footer count */}
517	      {!loading && !error && total > 0 && (
518	        <p className="text-[12px] text-gray-400 mt-1">
519	          Showing {filtered.length} discrepanc
520	          {filtered.length !== 1 ? 'ies' : 'y'} for {displayTail}
521	        </p>
522	      )}
523	    </div>
524	  );
525	}
