115	function isGroundingInspectionType(inspectionType?: string): boolean {
116	  if (!inspectionType) return false;
117	  const config = INSPECTION_TYPE_CONFIG[inspectionType];
118	  if (config?.grounding !== undefined) return config.grounding;
119	  const groundingPatterns = [
120	    'annual',
121	    '100-hour',
122	    '100 hour',
123	    'progressive',
124	    'elt',
125	    'altimeter',
126	    'transponder',
127	    'pitot',
128	    'static',
129	    'engine overhaul',
130	    'prop overhaul',
131	    'magneto',
132	    'ad compliance',
133	  ];
134	  const lc = inspectionType.toLowerCase();
135	  return groundingPatterns.some((p) => lc.includes(p));
136	}
