138	function statusLabel(status: RecordStatus): string {
139	  const map: Record<RecordStatus, string> = {
140	    open: 'Open',
141	    assigned: 'Assigned',
142	    pending: 'Scheduled',
143	    scheduled: 'Scheduled',
144	    'in-progress': 'In Progress',
145	    completed: 'Completed',
146	    overdue: 'Overdue',
147	    cancelled: 'Cancelled',
148	    voided: 'Voided',
149	  };
150	  return map[status] ?? status;
151	}
