161	      return 'bg-teal-100 text-teal-700';
162	    case 'completed':
163	      return 'bg-emerald-100 text-emerald-700';
164	    case 'voided':
165	    case 'cancelled':
166	      return 'bg-slate-100 text-slate-500';
167	    default:
168	      return 'bg-slate-100 text-slate-600';
169	  }
170	}
