172	function dueDateLabel(
173	  rec: InspectionRecord,
174	  hobbsTime: number,
175	  tachTime: number,
176	): string {
177	  if (rec.trackingType === 'hours' && rec.dueAtHours) {
178	    const meter = rec.meterType === 'tach' ? tachTime : hobbsTime;
179	    const remaining = rec.dueAtHours - meter;
180	    if (remaining <= 0)
181	      return `${Math.abs(Math.round(remaining * 10) / 10)} hrs overdue`;
182	    return `Due in ${Math.round(remaining * 10) / 10} ${rec.meterType ?? 'hobbs'} hrs`;
183	  }
184	  if (rec.dueDate) {
185	    const today = new Date();
186	    today.setHours(0, 0, 0, 0);
187	    const due = parseDateLocal(rec.dueDate);
188	    const diffDays = Math.round((due.getTime() - today.getTime()) / 86400000);
189	    if (diffDays < 0) return `${Math.abs(diffDays)} days overdue`;
190	    if (diffDays === 0) return 'Due today';
191	    if (diffDays === 1) return 'Due tomorrow';
192	    if (diffDays <= 30) return `Due in ${diffDays} days`;
193	    return `Due ${due.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;
194	  }
195	  return '';
196	}
