643	  const canDelete = user?.role === 'super_admin';
644	
645	  // ─── Fetch aircraft info ───────────────────────────────────────────────────
646	
647	  const loadAircraft = useCallback(async () => {
648	    if (!orgId || !equipmentId) return;
649	    try {
650	      const locationParam = activeLocation?.id
651	        ? `?locationId=${activeLocation.id}`
652	        : '';
653	      const res = await fetch(
654	        `${API}/schools/${orgId}/maintenance-hub/fleet-status${locationParam}`,
655	        { credentials: 'include' },
656	      );
657	      if (!res.ok) return;
