660	      setAircraft(rows.find((r) => r.id === equipmentId) ?? null);
661	    } catch {
662	      // aircraft info is supplemental; silently skip
663	    }
664	  }, [orgId, equipmentId, activeLocation?.id]);
665	
666	  // ─── Fetch maintenance records ─────────────────────────────────────────────
667	
668	  const loadRecords = useCallback(
669	    async (locationId: string) => {
670	      if (!equipmentId) return;
671	      try {
672	        const res = await fetch(
673	          `${API}/locations/${locationId}/equipment/${equipmentId}/maintenance`,
674	          { credentials: 'include' },
675	        );
676	        if (!res.ok) {
677	          console.error('[MHInspections] Load failed:', res.status);
678	          return;
679	        }
680	        const data = await res.json();
681	        const LOGBOOK_TYPES = new Set([
682	          'squawk_resolution',
683	          'inspection_completion',
684	          'phase_completion',
685	          'logbook',
686	        ]);
687	        const all = (Array.isArray(data) ? data : []).filter(
688	          (r: { type: string }) => !LOGBOOK_TYPES.has(r.type),
689	        );
690	
691	        const hobbsTime = Number(aircraft?.hobbsTime) || 0;
692	        const tachTime = Number(aircraft?.tachTime) || 0;
693	        const today = new Date();
694	        today.setHours(0, 0, 0, 0);
695	
696	        // Auto-detect overdue status
697	        let changed = false;
698	        const checked: InspectionRecord[] = all.map((r: InspectionRecord) => {
699	          if (
700	            r.type === 'inspection' &&

700	            r.type === 'inspection' &&
701	            (r.status === 'scheduled' ||
702	              r.status === 'pending' ||
703	              r.status === 'overdue')
704	          ) {
705	            let isOverdue = false;
706	            if (
707	              r.trackingType === 'hours' &&
708	              r.dueAtHours &&
709	              r.dueAtHours > 0
710	            ) {
711	              const meter = r.meterType === 'tach' ? tachTime : hobbsTime;
712	              if (r.progressivePhases && r.progressivePhases.length > 0) {
713	                const pending = r.progressivePhases.filter(
714	                  (p) => p.status !== 'completed',
715	                );
716	                isOverdue = pending.some((p) => meter >= p.dueAtHours);
717	              } else {
718	                isOverdue = meter >= r.dueAtHours;
719	              }
720	            }
721	            if (r.trackingType === 'date' && r.dueDate) {
722	              const due = parseDateLocal(r.dueDate);
723	              if (today > due) isOverdue = true;
724	            }
725	            if (isOverdue && r.status !== 'overdue') {
726	              changed = true;
727	              return {
728	                ...r,
729	                status: 'overdue' as RecordStatus,
730	                groundAircraft: isGroundingInspectionType(
731	                  r.inspectionType || r.title,
732	                ),
