736	              changed = true;
737	              return {
738	                ...r,
739	                status: 'scheduled' as RecordStatus,
740	                groundAircraft: false,
741	              };
742	            }
743	          }
744	          return r;
745	        });
746	
747	        const inspections = checked.filter((r) => r.type === 'inspection');
748	        setRecords(inspections);
749	
750	        if (changed) {
751	          try {
752	            await fetch(
753	              `${API}/locations/${locationId}/equipment/${equipmentId}/maintenance`,
754	              {
755	                method: 'PUT',
756	                headers: getServerApiHeaders(),
757	                credentials: 'include',
758	                body: JSON.stringify(checked),
