842	          assignedMechanics: result.assignedMechanics,
843	          autoGround: result.autoGround,
844	          notificationRecipients: result.notificationRecipients,
845	          notes: result.notes,
846	          trackingType: result.trackingType || 'date',
847	          meterType: result.meterType,
848	          interval: result.interval,
849	          intervalUnit: result.intervalUnit,
850	          dueAtHours: result.dueAtHours,
851	          farReference: result.farReference,
852	          progressivePhases: result.progressivePhases,
853	          leadTimes: result.leadTimes,
