551	// ─── Compression trend chart (SVG) ────────────────────────────────────────────
552	
553	function CompressionTrendChart({
554	  compressions,
555	}: {
556	  compressions: CompressionCheck[];
557	}) {
558	  const checks = compressions.slice(0, 6).reverse();
559	  if (checks.length < 2) {
560	    return (
561	      <div className="py-6 text-center text-xs text-gray-400">
562	        Need at least 2 compression checks to show trend. Log another check to
563	        enable this view.
564	      </div>
565	    );
566	  }
567	
568	  const sparseData = checks.length < 3;
569	
570	  const differential = checks[0]?.differentialPsi ?? 80;
571	  const cylCount = Math.max(...checks.map((c) => c.cylinderReadings.length));
572	  const cylColors = [
573	    '#0D9488',
574	    '#0284C7',
575	    '#7C3AED',
576	    '#DB2777',
577	    '#EA580C',
578	    '#16A34A',
579	  ];
580	
581	  const WIDTH = 480;
582	  const HEIGHT = 280;
583	  const PAD_L = 28;
584	  const PAD_R = 36;
585	  const PAD_T = 8;
586	  const PAD_B = 24;
587	  const CHART_W = WIDTH - PAD_L - PAD_R;
588	  const CHART_H = HEIGHT - PAD_T - PAD_B;
589	
590	  const allReadings = checks.flatMap((c) =>
591	    c.cylinderReadings.map((rd) => rd.reading),
592	  );
593	  const lowestReading = allReadings.length > 0 ? Math.min(...allReadings) : 50;
594	  const MIN_PSI = Math.min(50, lowestReading - 10);
595	  const MAX_PSI = differential;
596	  const PSI_RANGE = MAX_PSI - MIN_PSI;
597	
598	  function toX(idx: number) {
599	    return PAD_L + (idx / Math.max(checks.length - 1, 1)) * CHART_W;
600	  }
601	  function toY(psi: number) {
602	    return PAD_T + CHART_H - ((psi - MIN_PSI) / PSI_RANGE) * CHART_H;
603	  }
604	
605	  const baselineY = toY(MAX_PSI);
606	  const thresholdGood = toY(72);
607	  const thresholdWatch = toY(60);
608	  const chartBottom = PAD_T + CHART_H;
609	
610	  const cylIndices = Array.from({ length: cylCount }, (_, i) => i + 1);
611	
612	  return (
613	    <div className="space-y-2">
614	      <svg
615	        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
616	        className="w-full"
617	        style={{ height: '280px' }}
618	        aria-label="Cylinder compression trend chart"
619	      >
620	        {/* Background threshold zones */}
621	        <rect
622	          x={PAD_L}
623	          y={baselineY}
624	          width={CHART_W}
625	          height={thresholdGood - baselineY}
626	          fill="#F0FDF4"
627	        />
628	        <rect
629	          x={PAD_L}
630	          y={thresholdGood}
631	          width={CHART_W}
632	          height={thresholdWatch - thresholdGood}
633	          fill="#FFFBEB"
634	        />
635	        <rect
636	          x={PAD_L}
637	          y={thresholdWatch}
638	          width={CHART_W}
639	          height={chartBottom - thresholdWatch}
640	          fill="#FEF2F2"
641	        />
642	
643	        {/* 80 psi baseline reference */}
644	        <line
645	          x1={PAD_L}
646	          y1={baselineY}
647	          x2={WIDTH - PAD_R}
648	          y2={baselineY}
649	          stroke="#6B7280"
650	          strokeWidth={1}
651	          opacity={0.4}
652	        />
653	        <text x={2} y={baselineY + 3} fontSize={8} fill="#6B7280" opacity={0.6}>
654	          {MAX_PSI}
655	        </text>
656	
657	        {/* Good threshold line (72) */}
658	        <line
659	          x1={PAD_L}
660	          y1={thresholdGood}
661	          x2={WIDTH - PAD_R}
662	          y2={thresholdGood}
663	          stroke="#0D9488"
664	          strokeWidth={1}
665	          strokeDasharray="4 3"
666	          opacity={0.8}
667	        />
668	        <text
669	          x={2}
670	          y={thresholdGood + 3}
671	          fontSize={8}
672	          fill="#0D9488"
673	          opacity={0.9}
674	        >
675	          72
676	        </text>
677	
678	        {/* Watch threshold line (60) */}
679	        <line
680	          x1={PAD_L}
681	          y1={thresholdWatch}
682	          x2={WIDTH - PAD_R}
683	          y2={thresholdWatch}
684	          stroke="#F59E0B"
685	          strokeWidth={1}
686	          strokeDasharray="4 3"
687	          opacity={0.8}
688	        />
689	        <text
690	          x={2}
691	          y={thresholdWatch + 3}
692	          fontSize={8}
693	          fill="#F59E0B"
694	          opacity={0.9}
695	        >
696	          60
697	        </text>
698	
699	        {/* Lines per cylinder */}
700	        {cylIndices.map((cyl, ci) => {
701	          const points = checks.map((c, idx) => {
702	            const rd = c.cylinderReadings.find((r) => r.cyl === cyl);
703	            const psi = rd?.reading ?? MIN_PSI;
704	            const dateLabel = new Date(c.checkDate).toLocaleDateString(
705	              'en-US',
706	              {
707	                month: 'short',
708	                day: 'numeric',
709	                year: 'numeric',
710	              },
711	            );
712	            return { x: toX(idx), y: toY(psi), psi, dateLabel };
713	          });
714	          const d = points
715	            .map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`)
716	            .join(' ');
717	          const lastPt = points[points.length - 1];
718	          return (
719	            <g key={cyl}>
720	              {!sparseData && (
721	                <path
722	                  d={d}
723	                  fill="none"
724	                  stroke={cylColors[ci] ?? '#6B7280'}
725	                  strokeWidth={2}
726	                  strokeLinejoin="round"
727	                />
728	              )}
729	              {points.map((p, i) => (
730	                <circle
731	                  key={i}
732	                  cx={p.x}
733	                  cy={p.y}
734	                  r={4}
735	                  fill={cylColors[ci] ?? '#6B7280'}
736	                  stroke="white"
737	                  strokeWidth={1.5}
738	                >
739	                  <title>{`Cyl ${cyl}: ${p.psi} psi — ${p.dateLabel}`}</title>
740	                </circle>
741	              ))}
742	              {lastPt && (
743	                <text
744	                  x={lastPt.x + 8}
745	                  y={lastPt.y + 4}
746	                  fontSize={8}
747	                  fontWeight="600"
748	                  fill={cylColors[ci] ?? '#6B7280'}
749	                >
750	                  {lastPt.psi}
751	                </text>
752	              )}
753	            </g>
754	          );
755	        })}
756	
757	        {/* X-axis date labels */}
758	        {checks.map((c, idx) => (
759	          <text
760	            key={idx}
761	            x={toX(idx)}
762	            y={HEIGHT - 6}
763	            textAnchor="middle"
764	            fontSize={7}
765	            fill="#9CA3AF"
766	          >
767	            {new Date(c.checkDate).toLocaleDateString('en-US', {
768	              month: 'short',
769	              day: 'numeric',
770	            })}
771	          </text>
772	        ))}
773	      </svg>
774	
775	      {sparseData && (
776	        <p className="text-center text-[10px] text-gray-400 italic">
777	          Log more checks to see a full trend line.
778	        </p>
779	      )}
780	
781	      {/* Legend */}
782	      <div className="flex flex-wrap items-center gap-x-4 gap-y-1.5 pt-2 border-t border-gray-100">
783	        <div className="flex flex-wrap gap-3">
784	          {cylIndices.map((cyl, ci) => (
785	            <div key={cyl} className="flex items-center gap-1">
786	              <div
787	                className="w-4 h-1 rounded-full"
788	                style={{ backgroundColor: cylColors[ci] ?? '#6B7280' }}
789	              />
790	              <span className="text-[10px] text-gray-500">Cyl {cyl}</span>
791	            </div>
792	          ))}
793	        </div>
794	        <div className="flex flex-wrap gap-3 ml-auto">
795	          <div className="flex items-center gap-1">
796	            <span className="w-2.5 h-2.5 rounded-sm bg-green-50 border border-green-300 flex-shrink-0" />
797	            <span className="text-[10px] text-gray-400">Good ≥72</span>
798	          </div>
799	          <div className="flex items-center gap-1">
800	            <span className="w-2.5 h-2.5 rounded-sm bg-amber-50 border border-amber-300 flex-shrink-0" />
801	            <span className="text-[10px] text-gray-400">Watch 60–71</span>
802	          </div>
803	          <div className="flex items-center gap-1">
804	            <span className="w-2.5 h-2.5 rounded-sm bg-red-50 border border-red-300 flex-shrink-0" />
805	            <span className="text-[10px] text-gray-400">Squawk &lt;60</span>
806	          </div>
807	        </div>
808	      </div>
809	    </div>
810	  );
811	}
