813	// ─── Enhanced cylinder bars (with baseline + thresholds + weakest highlight) ──
814	
815	function EnhancedCylinderBars({ check }: { check: CompressionCheck }) {
816	  const readings = check.cylinderReadings ?? [];
817	  const differential = check.differentialPsi;
818	  const minReading =
819	    readings.length > 1 ? Math.min(...readings.map((r) => r.reading)) : -1;
820	
821	  const CHART_H = 80;
822	  // Extra vertical space at the top for the "Lowest" floating label (-top-5 = 20px)
823	  const LABEL_ABOVE = 20;
824	  const MIN_PSI = Math.min(50, ...readings.map((r) => r.reading)) - 5;
825	  const MAX_PSI = differential;
826	  const PSI_RANGE = MAX_PSI - MIN_PSI;
827	
828	  const goodThresholdFromBottom = ((72 - MIN_PSI) / PSI_RANGE) * CHART_H;
829	  const watchThresholdFromBottom = ((60 - MIN_PSI) / PSI_RANGE) * CHART_H;
830	
831	  function barH(reading: number) {
832	    return Math.max(4, ((reading - MIN_PSI) / PSI_RANGE) * CHART_H);
833	  }
834	
835	  return (
836	    <div>
837	      {/* Chart area: bars + threshold lines only — no text labels inside.
838	          Text labels are rendered below so the bars align correctly with the
839	          threshold lines (which use bottom:Xpx from the chart container). */}
840	      <div
841	        className="relative"
842	        style={{ height: `${CHART_H + LABEL_ABOVE}px` }}
843	      >
844	        {/* Threshold lines — positioned from chart bottom, matching bar scale */}
845	        <div
846	          className="absolute left-0 right-0 border-t border-dashed border-teal-400 pointer-events-none"
847	          style={{ bottom: `${goodThresholdFromBottom}px` }}
848	        >
849	          <span className="absolute right-0 bottom-0.5 text-[9px] text-teal-500 bg-white px-0.5">
850	            72
851	          </span>
852	        </div>
853	        <div
854	          className="absolute left-0 right-0 border-t border-dashed border-amber-400 pointer-events-none"
855	          style={{ bottom: `${watchThresholdFromBottom}px` }}
856	        >
857	          <span className="absolute right-0 bottom-0.5 text-[9px] text-amber-500 bg-white px-0.5">
858	            60
859	          </span>
860	        </div>
861	
862	        {/* Bars row — pinned to chart bottom so heights align with threshold lines */}
863	        <div className="absolute bottom-0 left-0 flex gap-4 items-end">
864	          {readings.map((r) => {
865	            const isWeakest = r.reading === minReading;
866	            return (
867	              <div
868	                key={r.cyl}
869	                className={cn(
870	                  'w-10 rounded-t-md transition-all relative',
871	                  cylColor(r.reading, differential),
872	                  isWeakest && 'ring-2 ring-offset-1 ring-gray-700',
873	                )}
874	                style={{ height: `${barH(r.reading)}px` }}
875	              >
876	                {isWeakest && readings.length > 1 && (
877	                  <span className="absolute -top-5 left-1/2 -translate-x-1/2 text-[9px] text-gray-600 font-semibold whitespace-nowrap">
878	                    Lowest
879	                  </span>
880	                )}
881	              </div>
882	            );
883	          })}
884	        </div>
885	      </div>
886	
887	      {/* Labels row — outside the chart container so they don't push bars up */}
888	      <div className="flex gap-4 mt-1">
889	        {readings.map((r) => (
890	          <div key={r.cyl} className="w-10 flex flex-col items-center gap-0.5">
891	            <span
892	              className={cn(
893	                'text-xs font-semibold',
894	                cylTextColor(r.reading, differential),
895	              )}
896	            >
897	              {r.reading}/{differential}
898	            </span>
899	            <span className="text-xs text-gray-400">Cyl {r.cyl}</span>
900	          </div>
901	        ))}
902	      </div>
903	
904	      <p className="text-[10px] text-gray-400 mt-1">
905	        Baseline: {differential} psi differential
906	      </p>
907	    </div>
908	  );
909	}
