37	// ─── Thresholds ───────────────────────────────────────────────────────────────
38	
39	/** Compression reading thresholds (out of 80 psi differential) */
40	const COMPRESSION_GOOD = 72;
41	const COMPRESSION_WATCH = 60;
42	
43	/** Metal reading thresholds (ppm) — Lycoming general limits */
44	const METAL_THRESHOLDS: Record<string, { watch: number; action: number }> = {
45	  iron: { watch: 60, action: 100 },
46	  copper: { watch: 25, action: 50 },
47	  chromium: { watch: 10, action: 20 },
48	  lead: { watch: 25, action: 50 },
49	  aluminum: { watch: 20, action: 40 },
50	};
51	
52	function getCompressionStatus(
53	  avg: number,
54	  differential: number,
55	): 'good' | 'watch' | 'action' {
56	  const threshold = differential;
57	  if (avg >= (COMPRESSION_GOOD / 80) * threshold) return 'good';
58	  if (avg >= (COMPRESSION_WATCH / 80) * threshold) return 'watch';
59	  return 'action';
60	}
61	
62	function getMetalStatus(
63	  metal: string,
64	  ppm: number,
65	): 'normal' | 'watch' | 'action' {
66	  const thresholds = METAL_THRESHOLDS[metal.toLowerCase()];
67	  if (!thresholds) return 'normal';
68	  if (ppm >= thresholds.action) return 'action';
69	  if (ppm >= thresholds.watch) return 'watch';
70	  return 'normal';
71	}
