219	
220	      // Compute oil analysis status
221	      let oilStatus: 'normal' | 'watch' | 'action' | null = null;
222	      if (latestOilAnalysis) {
223	        const metals =
224	          (latestOilAnalysis.metalReadings as Record<string, number | null>) ??
