237	
238	      // TBO stats — use tach time as industry-standard reference for TSMOH/TBO
239	      const tboHours = aircraft.tboHours ?? null;
240	      const currentTach = aircraft.tachTime ?? null;
241	      const hobbsAtLastTbo = aircraft.hobbsAtLastTbo ?? null;
242	      const timeSinceOverhaul =
243	        hobbsAtLastTbo !== null && currentTach !== null
244	          ? Math.max(0, currentTach - hobbsAtLastTbo)
245	          : (aircraft.timeSinceOverhaul ?? null);
246	      const tboPercent =
247	        tboHours && timeSinceOverhaul ? timeSinceOverhaul / tboHours : null;
