188	function formatDate(d: string): string {
189	  return new Date(d).toLocaleDateString('en-US', {
190	    month: 'short',
191	    day: 'numeric',
192	    year: 'numeric',
193	  });
194	}
195	
196	function formatHours(h: number | null | string | undefined): string {
197	  if (h === null || h === undefined || h === '') return '—';
198	  const n = typeof h === 'string' ? Number.parseFloat(h) : h;
199	  if (Number.isNaN(n)) return '—';
200	  return n.toLocaleString('en-US', {
201	    minimumFractionDigits: 1,
202	    maximumFractionDigits: 1,
203	  });
204	}
205	
206	function groupEntriesByYear(
207	  entries: LogbookEntry[],
208	): { year: string; entries: LogbookEntry[] }[] {
209	  const map: Record<string, LogbookEntry[]> = {};
210	  for (const e of entries) {
211	    const year = e.entryDate.substring(0, 4);
212	    if (!map[year]) map[year] = [];
213	    map[year].push(e);
214	  }
215	  return Object.entries(map)
216	    .sort(([a], [b]) => Number.parseInt(b) - Number.parseInt(a))
217	    .map(([year, entries]) => ({ year, entries }));
218	}
