244	function formatDate(dateStr: string): string {
245	  const d = new Date(`${dateStr}T12:00:00`);
246	  const year = d.getFullYear();
247	  const currentYear = new Date().getFullYear();
248	  const month = d.toLocaleString('en-US', { month: 'short' });
249	  const day = d.getDate();
250	  return year === currentYear ? `${month} ${day}` : `${month} ${day} ${year}`;
251	}
252	
253	function formatCurrency(value: number): string {
254	  return new Intl.NumberFormat('en-US', {
255	    style: 'currency',
256	    currency: 'USD',
257	    maximumFractionDigits: 0,
258	  }).format(value);
259	}
260	
261	function groupByYear(
262	  records: PartInstallation[],
263	): Map<number, PartInstallation[]> {
264	  const groups = new Map<number, PartInstallation[]>();
265	  for (const r of records) {
266	    const year = new Date(`${r.installedAt}T12:00:00`).getFullYear();
267	    const existing = groups.get(year) ?? [];
268	    groups.set(year, [...existing, r]);
269	  }
270	  return groups;
271	}
