273	function calcLifePercent(
274	  record: PartInstallation,
275	  currentHobbs: number,
276	): number | null {
277	  if (!record.expectedLifeHrs) return null;
278	  const hoursAtInstall = Number(record.aircraftHours);
279	  const hoursSince = currentHobbs - hoursAtInstall;
280	  return Math.min(Math.round((hoursSince / record.expectedLifeHrs) * 100), 100);
281	}
