131	type SortField = keyof FleetRow;
132	type SortDir = 'asc' | 'desc';
133	
134	function sortFleetRows(
135	  rows: FleetRow[],
136	  field: SortField,
137	  dir: SortDir,
138	): FleetRow[] {
139	  return [...rows].sort((a, b) => {
140	    const av = a[field];
141	    const bv = b[field];
142	    if (av === null && bv === null) return 0;
143	    if (av === null) return dir === 'asc' ? 1 : -1;
144	    if (bv === null) return dir === 'asc' ? -1 : 1;
145	    if (typeof av === 'number' && typeof bv === 'number') {
146	      return dir === 'asc' ? av - bv : bv - av;
147	    }
148	    const as = String(av).toLowerCase();
149	    const bs = String(bv).toLowerCase();
150	    return dir === 'asc' ? as.localeCompare(bs) : bs.localeCompare(as);
151	  });
152	}
