115	async function callClaude(
116	  prompt: string,
117	  systemPrompt: string,
118	  maxTokens = 256,
119	  schoolId?: string,
120	): Promise<{ text: string; inputTokens: number; outputTokens: number }> {
121	  const result = await aiGateway.generateText({
122	    featureKey: 'maintenance.intelligence',
123	    input: prompt,
124	    system: systemPrompt,
125	    tenantId: schoolId,
126	    parameters: { maxTokens },
127	    metadata: { legacyFeature: 'maintenance-intelligence' },
128	  });
129	  if (!result.text) throw new Error('No text in Claude response');
130	  return {
131	    text: result.text,
132	    inputTokens: result.usage.inputTokens,
133	    outputTokens: result.usage.outputTokens,
134	  };
135	}
