137	function riskLevel100Hr(
138	  hoursUntil: number | null,
139	): PredictiveAircraftRow['riskLevel100Hr'] {
140	  if (hoursUntil === null) return 'green';
141	  if (hoursUntil < 0) return 'overdue';
142	  if (hoursUntil < THRESHOLD_100HR_RED) return 'red';
143	  if (hoursUntil < THRESHOLD_100HR_AMBER) return 'amber';
144	  return 'green';
145	}
146	
147	function riskLevelDays(
148	  days: number | null,
149	): PredictiveAircraftRow['riskLevelAnnual'] {
150	  if (days === null) return 'unknown';
151	  if (days < 0) return 'overdue';
152	  if (days < 30) return 'red';
153	  if (days < 60) return 'amber';
154	  return 'green';
155	}
156	
157	function computeAnomalyScore(flags: string[]): number {
158	  if (flags.length === 0) return 0;
159	  const score = flags.reduce((acc, flag) => {
160	    if (flag.includes('WO increase')) return acc + 30;
161	    if (flag.includes('Repeated')) return acc + 25;
162	    if (flag.includes('AOG')) return acc + 40;
163	    if (flag.includes('maintenance for')) return acc + 20;
164	    return acc + 10;
165	  }, 0);
166	  return Math.min(score, 100);
167	}
168	
169	function buildEquipmentWhereClause(
170	  schoolId: string,
171	  scopedLocationId: string | undefined,
172	  activeLocationIds?: string[],
173	) {
174	  if (scopedLocationId) {
175	    return and(
176	      eq(schema.equipment.flightSchoolId, schoolId),
177	      eq(schema.equipment.locationId, scopedLocationId),
178	      eq(schema.equipment.type, 'Aircraft'),
179	    );
180	  }
181	  // When active location IDs are available, scope to those locations — this
182	  // matches the fleet-status endpoint (routes-schools.ts) which uses the same
183	  // inArray(activeLocationIds) pattern. Using isNotNull(locationId) alone would
184	  // include aircraft at inactive/test locations, causing duplicate tail rows
185	  // (same aircraft registered at an inactive location appears alongside the
186	  // active-location record) and null flight hours (schedule events only exist
187	  // for active-location equipment IDs).
188	  if (activeLocationIds && activeLocationIds.length > 0) {
189	    return and(
190	      eq(schema.equipment.flightSchoolId, schoolId),
191	      inArray(schema.equipment.locationId, activeLocationIds),
192	      eq(schema.equipment.type, 'Aircraft'),
193	    );
194	  }
195	  // Fall back: exclude orphaned (null locationId) records when no active
196	  // locations are available (e.g., school with no configured locations).
197	  return and(
198	    eq(schema.equipment.flightSchoolId, schoolId),
199	    isNotNull(schema.equipment.locationId),
200	    eq(schema.equipment.type, 'Aircraft'),
201	  );
202	}
