204	// ─── GET /maintenance-intelligence/:schoolId/predictive ───────────────────────
205	
206	maintenanceIntelligence.get(
207	  '/maintenance-intelligence/:schoolId/predictive',
208	  requireAuth(),
209	  async (c) => {
210	    try {
211	      const schoolId = c.req.param('schoolId') ?? '';
212	      if (!isUuid(schoolId)) return c.json({ error: 'Invalid school ID' }, 400);
213	
214	      const locationIdParam = c.req.query('locationId') ?? '';
215	      const scopedLocationId = isUuid(locationIdParam)
216	        ? locationIdParam
217	        : undefined;
218	      const now = new Date();
219	
220	      const activeLocations = !scopedLocationId
221	        ? await locationRepository.findBySchool(schoolId)
222	        : [];
223	      const activeLocationIds = activeLocations.map((l) => l.id);
224	
225	      const allEquipment =
226	        scopedLocationId || activeLocationIds.length > 0
227	          ? await db
228	              .select()
229	              .from(schema.equipment)
230	              .where(
231	                buildEquipmentWhereClause(
232	                  schoolId,
233	                  scopedLocationId,
234	                  activeLocationIds,
235	                ),
236	              )
237	              .orderBy(schema.equipment.tailNumber)
238	          : [];
239	
240	      if (allEquipment.length === 0) {
241	        return c.json<PredictiveResponse>({
242	          aircraft: [],
243	          generatedAt: now.toISOString(),
244	        });
245	      }
246	
247	      const equipmentIds = allEquipment.map((e) => e.id);
248	
249	      const maintRecords = await db
250	        .select()
251	        .from(schema.equipmentMaintenance)
252	        .where(
253	          and(
254	            eq(schema.equipmentMaintenance.flightSchoolId, schoolId),
255	            inArray(schema.equipmentMaintenance.equipmentId, equipmentIds),
256	          ),
257	        )
258	        .orderBy(desc(schema.equipmentMaintenance.updatedAt));
259	
260	      const maintByEquip = new Map<string, typeof maintRecords>();
261	      for (const rec of maintRecords) {
262	        const list = maintByEquip.get(rec.equipmentId) ?? [];
263	        list.push(rec);
264	        maintByEquip.set(rec.equipmentId, list);
265	      }
266	
267	      const aircraft: PredictiveAircraftRow[] = allEquipment.map((eq) => {
268	        const recs = maintByEquip.get(eq.id) ?? [];
269	
270	        // 100-hour tracking — look for a maintenance record with dueAtHours in metadata
271	        const hrRec = recs.find(
272	          (r) => r.type === '100hr' || r.type === '100-hour',
273	        );
274	        const dueAtHours100Hr =
275	          hrRec?.metadata != null &&
276	          typeof hrRec.metadata === 'object' &&
277	          'dueAtHours' in hrRec.metadata
278	            ? Number((hrRec.metadata as Record<string, unknown>).dueAtHours)
279	            : null;
280	        const currentHobbs = eq.hobbsTime ?? 0;
281	        const hoursUntil100Hr =
282	          dueAtHours100Hr !== null ? dueAtHours100Hr - currentHobbs : null;
283	
284	        // Annual inspection
285	        const annualRec = recs.find((r) => r.type === 'annual');
286	        const annualDueDate = annualRec?.dueDate
287	          ? annualRec.dueDate.toISOString().split('T')[0]
288	          : (eq.nextAnnual ?? null);
289	        const daysUntilAnnual = annualDueDate
290	          ? Math.floor(
291	              (new Date(annualDueDate).getTime() - now.getTime()) /
292	                (24 * 60 * 60 * 1000),
293	            )
294	          : null;
295	
296	        // ELT inspection
297	        const eltRec = recs.find((r) => r.type === 'elt');
298	        const eltDueDate = eltRec?.dueDate
299	          ? eltRec.dueDate.toISOString().split('T')[0]
300	          : null;
301	        const daysUntilELT = eltDueDate
302	          ? Math.floor(
303	              (new Date(eltDueDate).getTime() - now.getTime()) /
304	                (24 * 60 * 60 * 1000),
305	            )
306	          : null;
307	
308	        // Altimeter/transponder inspection
309	        const altTransRec = recs.find(
310	          (r) =>
311	            r.type === 'altimeter_transponder' ||
312	            r.type === 'altimeter/transponder',
313	        );
314	        const altTransDueDate = altTransRec?.dueDate
315	          ? altTransRec.dueDate.toISOString().split('T')[0]
316	          : null;
317	        const daysUntilAltTrans = altTransDueDate
318	          ? Math.floor(
319	              (new Date(altTransDueDate).getTime() - now.getTime()) /
320	                (24 * 60 * 60 * 1000),
321	            )
322	          : null;
323	
324	        // Estimate average flight hours per day: hobbsTime / aircraft age in days
325	        const createdAt = eq.createdAt
326	          ? new Date(eq.createdAt)
327	          : new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
328	        const ageInDays = Math.max(
329	          1,
330	          (now.getTime() - createdAt.getTime()) / (24 * 60 * 60 * 1000),
331	        );
332	        const avgFlightHoursPerDay =
333	          currentHobbs > 0
334	            ? Math.round((currentHobbs / ageInDays) * 100) / 100
335	            : null;
336	
337	        const projectedDaysTill100Hr =
338	          hoursUntil100Hr !== null &&
339	          avgFlightHoursPerDay !== null &&
340	          avgFlightHoursPerDay > 0
341	            ? Math.floor(hoursUntil100Hr / avgFlightHoursPerDay)
342	            : null;
343	
344	        return {
345	          equipmentId: eq.id,
346	          tailNumber: eq.tailNumber ?? eq.id,
347	          make: eq.make ?? '',
348	          model: eq.model ?? '',
349	          hobbsTime: eq.hobbsTime ?? null,
350	          dueAtHours100Hr,
351	          hoursUntil100Hr,
352	          annualDueDate,
353	          daysUntilAnnual,
354	          eltDueDate,
355	          daysUntilELT,
356	          altTransDueDate,
357	          daysUntilAltTrans,
358	          avgFlightHoursPerDay,
359	          projectedDaysTill100Hr,
360	          riskLevel100Hr: riskLevel100Hr(hoursUntil100Hr),
361	          riskLevelAnnual: riskLevelDays(daysUntilAnnual),
362	          status: eq.status ?? 'Available',
363	        };
364	      });
365	
366	      return c.json<PredictiveResponse>({
367	        aircraft,
368	        generatedAt: now.toISOString(),
369	      });
370	    } catch (err) {
371	      const msg =
372	        err instanceof Error
373	          ? err.message
374	          : typeof err === 'object' && err !== null
375	            ? JSON.stringify(err)
376	            : String(err);
377	      console.error('[maintenance-intelligence/predictive]', msg);
378	      return c.json({ error: 'Failed to load predictive data' }, 500);
379	    }
380	  },
381	);
