383	// ─── GET /maintenance-intelligence/:schoolId/anomalies ────────────────────────
384	
385	maintenanceIntelligence.get(
386	  '/maintenance-intelligence/:schoolId/anomalies',
387	  requireAuth(),
388	  async (c) => {
389	    try {
390	      const schoolId = c.req.param('schoolId') ?? '';
391	      if (!isUuid(schoolId)) return c.json({ error: 'Invalid school ID' }, 400);
392	
393	      const locationIdParam = c.req.query('locationId') ?? '';
394	      const scopedLocationId = isUuid(locationIdParam)
395	        ? locationIdParam
396	        : undefined;
397	      const now = new Date();
398	
399	      const activeLocations = !scopedLocationId
400	        ? await locationRepository.findBySchool(schoolId)

400	        ? await locationRepository.findBySchool(schoolId)
401	        : [];
402	      const activeLocationIds = activeLocations.map((l) => l.id);
403	
404	      const allEquipment =
405	        scopedLocationId || activeLocationIds.length > 0
406	          ? await db
407	              .select()
408	              .from(schema.equipment)
409	              .where(
410	                buildEquipmentWhereClause(
411	                  schoolId,
412	                  scopedLocationId,
413	                  activeLocationIds,
414	                ),
415	              )
416	              .orderBy(schema.equipment.tailNumber)
417	          : [];
418	
419	      if (allEquipment.length === 0) {
420	        return c.json<AnomalyResponse>({
421	          aircraft: [],
422	          aiNarrative: null,
423	          fleetAnomalyScore: 0,
424	          generatedAt: now.toISOString(),
425	        });
426	      }
427	
428	      const equipmentIds = allEquipment.map((e) => e.id);
429	      const oneEightyDaysAgo = new Date(
430	        now.getTime() - 180 * 24 * 60 * 60 * 1000,
431	      );
432	      const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
433	
434	      const recentWOs = await db
435	        .select({
436	          id: schema.workOrders.id,
437	          equipmentId: schema.workOrders.equipmentId,
438	          type: schema.workOrders.type,
439	          status: schema.workOrders.status,
440	          priority: schema.workOrders.priority,
441	          createdAt: schema.workOrders.createdAt,
442	          completedAt: schema.workOrders.completedAt,
443	        })
444	        .from(schema.workOrders)
445	        .where(
446	          and(
447	            eq(schema.workOrders.flightSchoolId, schoolId),
448	            inArray(schema.workOrders.equipmentId, equipmentIds),
449	            gte(schema.workOrders.createdAt, oneEightyDaysAgo),
450	          ),
451	        );
452	
453	      const woByEquip = new Map<string, typeof recentWOs>();
454	      for (const wo of recentWOs) {
455	        if (!wo.equipmentId) continue;
456	        const list = woByEquip.get(wo.equipmentId) ?? [];
457	        list.push(wo);
458	        woByEquip.set(wo.equipmentId, list);
459	      }
460	
461	      const aircraft: AnomalyAircraftRow[] = allEquipment.map((eq) => {
462	        const wos = woByEquip.get(eq.id) ?? [];
463	        const wos90d = wos.filter(
464	          (w) => new Date(w.createdAt) >= ninetyDaysAgo,
465	        );
466	        const wosPrior90d = wos.filter(
467	          (w) =>
468	            new Date(w.createdAt) >= oneEightyDaysAgo &&
469	            new Date(w.createdAt) < ninetyDaysAgo,
470	        );
471	
472	        const flags: string[] = [];
473	
474	        // Flag: significant WO count increase
475	        let woIncreasePct: number | null = null;
476	        if (wosPrior90d.length > 0) {
477	          woIncreasePct =
478	            (wos90d.length - wosPrior90d.length) / wosPrior90d.length;
479	          if (woIncreasePct > ANOMALY_WO_INCREASE_RATIO) {
480	            flags.push(
481	              `WO increase: ${Math.round(woIncreasePct * 100)}% more work orders vs prior 90 days`,
482	            );
483	          }
484	        } else if (wos90d.length >= 3) {
485	          flags.push(
486	            `WO increase: ${wos90d.length} work orders in 90 days (no prior period data)`,
487	          );
488	        }
489	
490	        // Flag: repeated WO types
491	        const typeCounts = new Map<string, number>();
492	        for (const wo of wos90d) {
493	          typeCounts.set(wo.type, (typeCounts.get(wo.type) ?? 0) + 1);
494	        }
495	        const repeatedWoTypes: AnomalyAircraftRow['repeatedWoTypes'] = [];
496	        for (const [type, count] of typeCounts) {
497	          if (count >= 2) {
498	            repeatedWoTypes.push({ type, count });
499	            flags.push(`Repeated "${type}" work orders: ${count}x in 90 days`);
500	          }
501	        }
502	        repeatedWoTypes.sort((a, b) => b.count - a.count);
503	
504	        // Flag: AOG events
505	        const aogWOs = wos90d.filter((w) => w.priority === 'aog');
506	        if (aogWOs.length > 0) {
507	          flags.push(
508	            `AOG events: ${aogWOs.length} aircraft-on-ground work order(s) in 90 days`,
509	          );
510	        }
511	
512	        // Days since last completed maintenance
513	        const completedWOs = wos
514	          .filter((w) => w.completedAt !== null)
515	          .sort(
516	            (a, b) =>
517	              new Date(b.completedAt!).getTime() -
518	              new Date(a.completedAt!).getTime(),
519	          );
520	        const lastMaintenanceAt = completedWOs[0]?.completedAt
521	          ? new Date(completedWOs[0].completedAt)
522	          : null;
523	        const daysSinceLastMaintenance = lastMaintenanceAt
524	          ? Math.floor(
525	              (now.getTime() - lastMaintenanceAt.getTime()) /
526	                (24 * 60 * 60 * 1000),
527	            )
528	          : null;
529	
530	        // Flag: stuck in maintenance status
531	        const eqStatus = (eq.status ?? '').toLowerCase();
532	        if (eqStatus === 'maintenance' || eqStatus === 'in maintenance') {
533	          const openWO = wos.find(
534	            (w) =>
535	              w.status === 'in_progress' ||
536	              w.status === 'awaiting_parts' ||
537	              w.status === 'pending_inspection',
538	          );
